text:
Onde olhar
Seções com % sem digital alto no 1º turno e Δ margem extremo na própria UF. O ponto no extremo é prioridade de leitura, não um veredito.

viewof ufAnom = Inputs.select(
  ["ALL", ...rows.map(d =&gt; d.uf)],
  {label: "UF", format: d =&gt; d === "ALL" ? "Todas" : nomeUf(d), value: "ALL"}
)







pts = anomalias
  .filter(d =&gt; ufAnom === "ALL" || d.uf === ufAnom)
  .map(d =&gt; ({
    uf: d.uf,
    join_key: d.join_key,
    pct_sem_digital_1t: num(d.pct_sem_digital_1t),
    delta_margem_pp: num(d.delta_margem_pp),
    nivel: String(d.nivel || "").toUpperCase()
  }))
  .filter(d =&gt; d.pct_sem_digital_1t != null && d.delta_margem_pp != null)
nivelB = pts.filter(d =&gt; d.nivel === "B")
nPts = pts.length
nB = nivelB.length
Plot.plot({
  marginLeft: 64,
  marginBottom: 48,
  width: 1000,
  height: 480,
  x: {label: "% sem digital no 1º turno", grid: true},
  y: {label: "Δ margem (pp dos válidos, Lula − Flávio)", grid: true},
  color: {scheme: "Blues", legend: true, label: "Seções"},
  marks: [
    Plot.rect(pts, Plot.bin({fill: "count"}, {x: "pct_sem_digital_1t", y: "delta_margem_pp"})),
    Plot.dot(nivelB, {x: "pct_sem_digital_1t", y: "delta_margem_pp", fill: "#a51c1c", r: 3, tip: true}),
    Plot.ruleY([0], {stroke: "#999"})
  ]
})





































md`**${ufAnom === "ALL" ? "Todas as UFs" : nomeUf(ufAnom)}:** ${nPts.toLocaleString("pt-BR")} seções no mapa · ${nB.toLocaleString("pt-BR")} de nível B em vermelho. Positivo: a margem Lula (13) − Flávio (22), em pontos percentuais dos válidos, cresceu no 2º turno.`







lista = outliers
  .filter(d =&gt; ufAnom === "ALL" || d.uf === ufAnom)
  .slice()
  .sort((a, b) =&gt; (num(b.pct_sem_digital) || 0) - (num(a.pct_sem_digital) || 0))
html`&lt;div style="overflow-x:auto"&gt;&lt;table class="table table-sm"&gt;
  &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Seção&lt;/th&gt;&lt;th&gt;UF&lt;/th&gt;&lt;th&gt;Município&lt;/th&gt;&lt;th&gt;Comparecimento&lt;/th&gt;&lt;th&gt;% sem digital&lt;/th&gt;&lt;th&gt;Δ margem (pp, Lula − Flávio)&lt;/th&gt;&lt;th&gt;Flags&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
  &lt;tbody&gt;${lista.map(d =&gt; html`&lt;tr&gt;
    &lt;td&gt;&lt;a href="secao.html?uf=${d.uf}&mun=${+d.municipio}&zona=${+d.zona}&secao=${+d.secao}"&gt;${d.join_key}&lt;/a&gt;&lt;/td&gt;
    &lt;td&gt;${nomeUf(d.uf)}&lt;/td&gt;
    &lt;td&gt;${d.nome}&lt;/td&gt;
    &lt;td&gt;${fmt(d.bu_comparecimento)}&lt;/td&gt;
    &lt;td&gt;${fmt1(num(d.pct_sem_digital))}%&lt;/td&gt;
    &lt;td&gt;${pp(num(d.delta_margem_pp))}&lt;/td&gt;
    &lt;td&gt;${d.flags || "—"}&lt;/td&gt;
  &lt;/tr&gt;`)}&lt;/tbody&gt;
&lt;/table&gt;&lt;/div&gt;`





















Nota% sem digital muito alto



Dois caminhos do boletim empurram esse percentual para cima, e os dois são previstos no fluxo da urna. Quem já tinha biometria cadastrada pode ser habilitado pelo ano de nascimento quando a digital não confirma. Quem não tinha biometria cadastrada comparece por esse outro caminho. Nenhum dos dois é voto em candidato.
O Espírito Santo fica em 27,3% no 1º turno. Nas demais UFs a mediana é 10,4% e o maior valor, em Minas Gerais, é 17,9%.








NotaComo ler





O mapa de fundo é a densidade de todas as seções. Os pontos vermelhos são só o nível B: dois ou mais sinais independentes no percentil 99 da própria UF. A lista traz seções no topo de % sem digital, com o link da consulta por seção.

Fluxo do dia
Habilitação no log, não voto em candidato. O eixo é a fatia do dia, para os dois turnos caberem na mesma escala. Horário de Brasília; no exterior, horário local do posto.

ufsComHora = [...new Set(horas.map(d =&gt; d.uf))].sort()
viewof ufHora = Inputs.select(["BR", ...ufsComHora], {
  label: "UF",
  format: d =&gt; d === "BR" ? "Brasil (sem o exterior)" : nomeUf(d),
  value: "BR"
})
















aggPorBrt = (subset, turno) =&gt; {
  const m = new Map(d3.range(24).map(h =&gt; [h, {hora: h, n: 0, turno}]));
  for (const d of subset) {
    if (+d.turno !== turno) continue
    const h = +d.hora_brasilia
    if (!m.has(h)) continue
    m.get(h).n += +d.habilitacoes
  }
  return [...m.values()].sort((a, b) =&gt; a.hora - b.hora)
}
baseHoras = ufHora === "BR" ? horas.filter(d =&gt; d.uf !== "ZZ") : horas.filter(d =&gt; d.uf === ufHora)
serie1 = aggPorBrt(baseHoras, 1)
serie2 = aggPorBrt(baseHoras, 2)
tot1 = d3.sum(serie1, d =&gt; d.n)
tot2 = d3.sum(serie2, d =&gt; d.n)
apos1 = d3.sum(serie1.filter(d =&gt; d.hora &gt;= 17), d =&gt; d.n)
apos2 = d3.sum(serie2.filter(d =&gt; d.hora &gt;= 17), d =&gt; d.n)
emPct = (serie, tot) =&gt; serie.map(d =&gt; ({...d, pct: tot ? 100 * d.n / tot : 0}))
p1 = emPct(serie1, tot1)
p2 = emPct(serie2, tot2)
eixoLabel = ufHora === "ZZ" ? "Hora local (exterior)" : "Hora de Brasília"






















































































Plot.plot({
  marginLeft: 56,
  marginBottom: 44,
  width: 1000,
  height: 420,
  x: {label: eixoLabel, domain: d3.range(24), ticks: 24},
  y: {label: "% das habilitações do dia", grid: true, tickFormat: d =&gt; d.toLocaleString("pt-BR")},
  marks: [
    Plot.ruleY([0]),
    Plot.ruleX([17], {stroke: "#a51c1c", strokeOpacity: 0.35, strokeDasharray: "4,4"}),
    Plot.lineY(p1, {x: "hora", y: "pct", stroke: "#1f4e79", strokeWidth: 2, curve: "step"}),
    Plot.lineY(p2, {x: "hora", y: "pct", stroke: "#c47d1a", strokeWidth: 2, curve: "step", strokeDasharray: "6,3"})
  ]
})






Azul contínuo = 1º turno. Âmbar tracejado = 2º turno. A linha vertical é 17h.

horaTabela = d3.range(24).flatMap(h =&gt; {
  const a = p1.find(d =&gt; d.hora === h)
  const b = p2.find(d =&gt; d.hora === h)
  const n1 = a ? a.n : 0
  const n2 = b ? b.n : 0
  if (!n1 && !n2) return []
  return [{
    hora: h,
    n1, n2,
    q1: tot1 ? 100 * n1 / tot1 : 0,
    q2: tot2 ? 100 * n2 / tot2 : 0
  }]
})
html`&lt;details&gt;
  &lt;summary&gt;Hora a hora&lt;/summary&gt;
  &lt;div style="overflow-x:auto"&gt;&lt;table class="table table-sm"&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Hora&lt;/th&gt;&lt;th&gt;Habilitações 1º&lt;/th&gt;&lt;th&gt;% do dia 1º&lt;/th&gt;&lt;th&gt;Habilitações 2º&lt;/th&gt;&lt;th&gt;% do dia 2º&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;${horaTabela.map(d =&gt; html`&lt;tr&gt;
      &lt;td&gt;${String(d.hora).padStart(2, "0")}h${d.hora &gt;= 17 ? " · após 17h" : ""}&lt;/td&gt;
      &lt;td&gt;${fmt(d.n1)}&lt;/td&gt;&lt;td&gt;${fmt1(d.q1)}%&lt;/td&gt;
      &lt;td&gt;${fmt(d.n2)}&lt;/td&gt;&lt;td&gt;${fmt1(d.q2)}%&lt;/td&gt;
    &lt;/tr&gt;`)}&lt;/tbody&gt;
  &lt;/table&gt;&lt;/div&gt;
&lt;/details&gt;`
















md`**${ufHora === "BR" ? "Brasil, sem o exterior" : nomeUf(ufHora)}.** Habilitações 1º **${fmt(tot1)}** · 2º **${fmt(tot2)}** · após 17h **${fmt2(tot1 ? 100 * apos1 / tot1 : null)}%** no 1º e **${fmt2(tot2 ? 100 * apos2 / tot2 : null)}%** no 2º.`






No país, cerca de 2,9% das habilitações do 1º turno e 0,02% das do 2º caem às 17h ou depois. Os dois turnos usam a mesma regra: dia oficial mais ou menos 3 dias, e a mesma conversão para o horário de Brasília. O pacote do 2º turno traz o histórico do 1º, e esse histórico fica de fora da curva. O pacote do 1º turno não tem outro dia dentro da tolerância. O que sobra é a fila do encerramento. No 1º turno a hora das 17h ainda carrega uma fatia da tarde, mais forte no Norte e no Nordeste (Alagoas 9,1%, Bahia 7,3%). No 2º turno essa hora praticamente zera. O fuso não produz o salto: nos estados em UTC−3 a hora local e a de Brasília são a mesma, e o 1º turno continua alto.






NotaComo ler





A curva é o ritmo de habilitação no log do dia oficial. Pico fora de 8h–17h pede checagem de relógio e de evento de outro dia, não leitura de voto. O 1º turno teve mais cargos na cédula; a fila das 17h é compatível com isso. O 2º turno esvazia antes do encerramento.



A assinatura de hardware, com a cadeia fechada e a cadeia aberta, está em Integridade dos arquivos.

Esta página estima como os votos do 1º turno podem ter se repartido no 2º, a partir dos totais divulgados.
Esses totais são aceitos como dados: a leitura não valida nem invalida se o que foi divulgado é o que aconteceu.

turnos = FileAttachment("data/migracao/turnos.csv").csv({typed: true})
fluxo = FileAttachment("data/migracao/fluxo.csv").csv({typed: true})
cobertura = FileAttachment("data/migracao/cobertura.csv").csv({typed: true})
conferencia = FileAttachment("data/migracao/conferencia.csv").csv({typed: true})
nome = ({
  "13": "Lula (13)",
  "22": "Flávio (22)",
  eliminados: "Eliminados",
  branco_nulo: "Branco e nulo",
  abstencao: "Abstenção"
})
COR = ({
  "13": "#a51c1c",
  "22": "#1f4e79",
  eliminados: "#6b7280",
  branco_nulo: "#9ca3af",
  abstencao: "#c4a35a"
})
origensVis = ["13", "22", "eliminados", "branco_nulo", "abstencao"]
destinosVis = ["13", "22", "branco_nulo", "abstencao"]
partes = grupo =&gt; grupo === "branco_nulo" ? ["branco", "nulo"] : [grupo]
fmt = n =&gt; Math.round(+n || 0).toLocaleString("pt-BR")
pct = taxa =&gt; taxa == null || Number.isNaN(+taxa)
  ? "—"
  : (100 * +taxa).toLocaleString("pt-BR", {minimumFractionDigits: 1, maximumFractionDigits: 1}) + "%"
pct2 = taxa =&gt; (100 * taxa).toLocaleString("pt-BR", {minimumFractionDigits: 2, maximumFractionDigits: 2}) + "%"
pp = delta =&gt; {
  if (delta == null || Number.isNaN(+delta)) return "—"
  const sinal = delta &gt; 0 ? "+" : ""
  return `${sinal}${(+delta).toLocaleString("pt-BR", {minimumFractionDigits: 1, maximumFractionDigits: 1})} pp`
}
deltaTxt = (depois, antes) =&gt; {
  const d = Math.round(depois) - Math.round(antes)
  const sinal = d &gt; 0 ? "+" : ""
  return `${sinal}${fmt(d)}`
}
nomeUf = uf =&gt; uf === "ZZ" ? "Exterior" : uf
cob = cobertura[0] || {n_presentes: 0, n_ufs: 28, faltam: "", presentes: ""}
votosTurno = (uf, turno, grupo) =&gt; {
  const achou = turnos.find(d =&gt; d.uf === uf && +d.turno === turno && String(d.grupo) === grupo)
  return achou ? +achou.votos : 0
}
votosGrupo = (uf, turno, grupo) =&gt; partes(grupo).reduce((s, g) =&gt; s + votosTurno(uf, turno, g), 0)
ufsTurno = turno =&gt; [...new Set(turnos.filter(d =&gt; +d.turno === turno).map(d =&gt; d.uf))].sort()
votosPais = (turno, grupo) =&gt; ufsTurno(turno).reduce((s, uf) =&gt; s + votosGrupo(uf, turno, grupo), 0)
validosPais = turno =&gt; turno === 1
  ? votosPais(1, "13") + votosPais(1, "22") + votosPais(1, "eliminados")
  : votosPais(2, "13") + votosPais(2, "22")
totalBoletim = turno =&gt; ["13", "22", "eliminados", "branco_nulo", "abstencao"]
  .filter(g =&gt; !(turno === 2 && g === "eliminados"))
  .reduce((s, g) =&gt; s + votosPais(turno, g), 0)
vencedor = (uf, turno) =&gt; {
  const lula = votosTurno(uf, turno, "13")
  const flavio = votosTurno(uf, turno, "22")
  if (lula &gt; flavio) return "lula"
  if (flavio &gt; lula) return "flavio"
  return ""
}
classeUf = (uf, turno = 2) =&gt; {
  const v = vencedor(uf, turno)
  return v === "lula" ? "uf-lula" : v === "flavio" ? "uf-flavio" : ""
}
linhaFluxo = (uf, modelo, origem, destino) =&gt; fluxo.find(d =&gt;
  d.uf === uf && d.modelo === modelo && String(d.origem) === String(origem) && String(d.destino) === String(destino)
)
celulaFluxo = (uf, modelo, origem, destino) =&gt; {
  const origens = partes(origem)
  const destinos = partes(destino)
  let votos = 0
  let base = 0
  let tem = false
  const todosDestinos = ["13", "22", "branco", "nulo", "abstencao"]
  for (const o of origens) {
    for (const d of todosDestinos) {
      const row = linhaFluxo(uf, modelo, o, d)
      if (!row) continue
      tem = true
      const n = Math.round(+row.votos || 0)
      base += n
      if (destinos.includes(d)) votos += n
    }
  }
  if (!tem) return null
  return {votos, taxa: base ? votos / base : null}
}
ufsFluxo = [...new Set(fluxo.map(d =&gt; d.uf))].filter(uf =&gt; uf !== "BR").sort()
obsDestino = (uf, destino) =&gt; uf === "BR"
  ? ufsFluxo.reduce((s, u) =&gt; s + votosGrupo(u, 2, destino), 0)
  : votosGrupo(uf, 2, destino)
abstOrigem = (uf, modelo) =&gt; destinosVis.reduce((s, d) =&gt; s + (celulaFluxo(uf, modelo, "abstencao", d)?.votos || 0), 0)
totalMatriz = (uf, modelo) =&gt; origensVis.reduce((s, o) =&gt; s + destinosVis.reduce((t, d) =&gt; t + (celulaFluxo(uf, modelo, o, d)?.votos || 0), 0), 0)
textoDif = (est, obs) =&gt; {
  if (est == null) return "—"
  const d = Math.round(est) - Math.round(obs)
  if (d === 0) return "bate"
  const rel = obs ? pct2(d / obs) : "—"
  const sinal = d &gt; 0 ? "+" : ""
  return `${sinal}${fmt(d)} (${sinal}${rel})`
}
estimadoColuna = (uf, modelo, destino) =&gt; origensVis.reduce((s, o) =&gt; s + (celulaFluxo(uf, modelo, o, destino)?.votos || 0), 0)
erroRel = (uf, modelo, destino) =&gt; {
  const obs = obsDestino(uf, destino)
  if (!obs) return null
  return (estimadoColuna(uf, modelo, destino) - obs) / obs
}
divCelula = (uf, o, d) =&gt; {
  const bp = celulaFluxo(uf, "brown_payne", o, d)
  const lp = celulaFluxo(uf, "lphom", o, d)
  if (!bp || !lp || bp.taxa == null || lp.taxa == null) return null
  return (lp.taxa - bp.taxa) * 100
}
numTaxa = v =&gt; (v == null || v === "" || Number.isNaN(+v) ? null : +v)
saldoTaxa = (uf, modelo, origem) =&gt; {
  const a = celulaFluxo(uf, modelo, origem, "13")
  const b = celulaFluxo(uf, modelo, origem, "22")
  if (!a || !b || a.taxa == null || b.taxa == null) return null
  return a.taxa - b.taxa
}
ladoSaldo = saldo =&gt; saldo == null ? "" : saldo &gt; 0 ? "Lula" : saldo &lt; 0 ? "Flávio" : ""
favorece = (uf, origem) =&gt; {
  const a = ladoSaldo(saldoTaxa(uf, "brown_payne", origem))
  const b = ladoSaldo(saldoTaxa(uf, "lphom", origem))
  if (!a || !b || a !== b) return "depende do modelo"
  return a
}
intervaloCruza = (uf, origem) =&gt; {
  let lo = 0
  let hi = 0
  let peso = 0
  for (const o of partes(origem)) {
    const base = ["13", "22", "branco", "nulo", "abstencao"].reduce((s, d) =&gt; {
      const row = linhaFluxo(uf, "brown_payne", o, d)
      return s + (row ? Math.round(+row.votos || 0) : 0)
    }, 0)
    if (!base) continue
    const a = linhaFluxo(uf, "brown_payne", o, "13")
    const b = linhaFluxo(uf, "brown_payne", o, "22")
    const loA = numTaxa(a && a.taxa_lo)
    const hiA = numTaxa(a && a.taxa_hi)
    const loB = numTaxa(b && b.taxa_lo)
    const hiB = numTaxa(b && b.taxa_hi)
    if (loA == null || hiA == null || loB == null || hiB == null) return false
    lo += base * (loA - hiB)
    hi += base * (hiA - loB)
    peso += base
  }
  return peso &gt; 0 && lo &lt; 0 && hi &gt; 0
}
textoFavorece = (uf, origem) =&gt; {
  const base = favorece(uf, origem)
  return intervaloCruza(uf, origem) ? `${base} · intervalo cruza zero` : base
}
eleitoradoUf = uf =&gt; ["13", "22", "eliminados", "branco", "nulo", "abstencao"].reduce((s, g) =&gt; s + votosTurno(uf, 1, g), 0)
pesoOrigem = (uf, origem) =&gt; {
  const el = eleitoradoUf(uf)
  if (!el) return 0
  const votos = origem === "branco_nulo"
    ? votosTurno(uf, 1, "branco") + votosTurno(uf, 1, "nulo")
    : votosTurno(uf, 1, origem)
  return votos / el
}
celulasDiv = [
  ["eliminados", "13"],
  ["eliminados", "22"],
  ["branco_nulo", "13"],
  ["abstencao", "13"],
  ["abstencao", "22"]
]
divRelevante = uf =&gt; {
  const vals = celulasDiv
    .filter(([o]) =&gt; pesoOrigem(uf, o) &gt;= 0.01)
    .map(([o, d]) =&gt; divCelula(uf, o, d))
    .filter(v =&gt; v != null)
    .map(v =&gt; Math.abs(v))
  return vals.length ? Math.max(...vals) : 0
}
erroGrupo = (uf, destinos) =&gt; {
  const vals = destinos.flatMap(d =&gt; ["brown_payne", "lphom"].map(m =&gt; erroRel(uf, m, d))).filter(v =&gt; v != null).map(v =&gt; Math.abs(v))
  return vals.length ? Math.max(...vals) : null
}
leituraUf = uf =&gt; {
  if (favorece(uf, "eliminados") === "depende do modelo" || favorece(uf, "branco_nulo") === "depende do modelo") return "Indeterminada"
  return divRelevante(uf) &gt; 10 ? "Sensível" : "Robusta"
}
classeLeitura = nivel =&gt; nivel === "Robusta" ? "leitura-robusta" : nivel === "Sensível" ? "leitura-sensivel" : "leitura-indeterminada"
















































































































































































































































































































































NotaComo ler e metodologia





Brown e Payne e lphom partem dos mesmos boletins e devolvem uma matriz: de cada origem (Lula, Flávio, eliminados, branco e nulo, abstenção) para cada destino do 2º turno. A seção não tem taxa própria. A matriz da cidade, quando há seções suficientes, é a que entra na soma do estado.
Cada célula da matriz numérica é o voto transferido e a taxa sobre a origem. A soma da linha fecha em 100%. O total da coluna é o 2º turno estimado. No mapa de calor, a cor é essa taxa; o tooltip traz a taxa e o voto. Os dois modelos ficam em abas separadas. A aba Diferença é lphom − Brown e Payne, em pontos percentuais (pp).
A barra empilhada reparte a parcela dos válidos estimados. Válidos no 1º turno: Lula (13), Flávio (22) e eliminados. No 2º: Lula (13) e Flávio (22). Branco, nulo e abstenção não entram nesse percentual; na barra, aparecem só como origem.
A diferença do ajuste é o estimado menos o divulgado. Ela mede o quanto uma matriz única deixa de reproduzir o boletim.
Na tabela por estado, a linha vermelha é Lula à frente no 2º turno e a azul é Flávio. “% dos válidos” usa só o voto nominal. “% do eleitorado” é a fatia da linha, com a abstenção. “Fatia do país” é a parte do total nacional. ZZ aparece como Exterior.
A leitura de cada UF compara os dois modelos, sem usar solução de canto: o lphom encosta em 0% ou 100% por construção do programa linear.
“Eliminados favorecem” e “Branco e nulo favorecem” olham o saldo da origem (para Lula menos para Flávio). O mesmo sinal nos dois modelos vira “Lula” ou “Flávio”. Sinais opostos viram “depende do modelo”. Quando Brown e Payne tem intervalo de 95% nas duas taxas do saldo e esse intervalo cruza zero, a célula também diz isso. Célula sem intervalo não recebe essa marca.
“Divergência máx.” é o maior |lphom − Brown e Payne| em pp, só nas células Eliminados→Lula, Eliminados→Flávio, Branco e nulo→Lula, Abstenção→Lula e Abstenção→Flávio. Origem com menos de 1% do eleitorado da UF no 1º turno (votos nominais, brancos, nulos e abstenção) fica de fora dessa conta.
“Erro candidatos” é o maior |estimado − divulgado| / divulgado de Lula e de Flávio, nos dois modelos. “Erro branco e nulo” é a mesma conta para branco e nulo somados.
Robusta: os dois saldos concordam entre os modelos e a divergência fica em até 10 pp. Sensível: os saldos concordam e a divergência passa de 10 pp. Indeterminada: pelo menos um saldo muda de lado conforme o modelo. O intervalo que cruza zero é uma marca na célula; não muda sozinho o nível.
Cores: Lula (13) vermelho, Flávio (22) azul, eliminados cinza, branco e nulo cinza-claro, abstenção dourado.







