Plotly = require("https://cdn.plot.ly/plotly-2.35.2.min.js")
sankey = (uf, modelo) =&gt; {
  const nos = [
    ...origensVis.map(o =&gt; ({nome: `${nome[o]} · 1º`, cor: COR[o]})),
    ...destinosVis.map(d =&gt; ({nome: `${nome[d]} · 2º`, cor: COR[d]}))
  ]
  const links = []
  for (const o of origensVis) {
    for (const d of destinosVis) {
      const cel = celulaFluxo(uf, modelo, o, d)
      if (!cel || !cel.votos) continue
      links.push({
        source: origensVis.indexOf(o),
        target: origensVis.length + destinosVis.indexOf(d),
        value: cel.votos,
        rotulo: `${nome[o]} → ${nome[d]}: ${fmt(cel.votos)} (${pct(cel.taxa)} da origem)`
      })
    }
  }
  const div = document.createElement("div")
  div.style.minHeight = "520px"
  Plotly.newPlot(div, [{
    type: "sankey",
    orientation: "h",
    node: {label: nos.map(n =&gt; n.nome), color: nos.map(n =&gt; n.cor), pad: 16, thickness: 16, line: {color: "#fff", width: 0}},
    link: {
      source: links.map(l =&gt; l.source),
      target: links.map(l =&gt; l.target),
      value: links.map(l =&gt; l.value),
      customdata: links.map(l =&gt; l.rotulo),
      hovertemplate: "%{customdata}&lt;extra&gt;&lt;/extra&gt;",
      color: "rgba(120,120,120,0.28)"
    }
  }], {
    font: {family: "inherit", size: 12},
    margin: {l: 8, r: 8, t: 12, b: 8},
    height: 520
  }, {displayModeBar: false, responsive: true})
  return div
}
