ORIGENS = ["13", "22", "eliminados", "branco", "nulo", "abstencao"]
DESTINOS = ["13", "22", "branco", "nulo", "abstencao"]
VIS_O = ["13", "22", "eliminados", "branco_nulo", "abstencao"]
VIS_D = ["13", "22", "branco_nulo", "abstencao"]
partes = (k) =&gt; k === "branco_nulo" ? ["branco", "nulo"] : [k]
votosVis = (margem, k) =&gt; partes(k).reduce((s, p) =&gt; s + (margem[p] || 0), 0)
vazioO = () =&gt; ({"13": 0, "22": 0, eliminados: 0, branco: 0, nulo: 0, abstencao: 0})
vazioD = () =&gt; ({"13": 0, "22": 0, branco: 0, nulo: 0, abstencao: 0})
acumula = (spec, dest, turno) =&gt; {
  if (!spec) return
  for (const part of String(spec).split("|").filter(Boolean)) {
    const [cod, qtd] = part.split("=")
    const n = +qtd || 0
    if (cod === "13") dest["13"] += n
    else if (cod === "22") dest["22"] += n
    else if (cod === "95") dest.branco += n
    else if (cod === "96") dest.nulo += n
    else if (turno === 1) dest.eliminados += n
  }
}
margemDe = (row) =&gt; {
  const o = vazioO()
  const d = vazioD()
  acumula(row.t1, o, 1)
  acumula(row.t2, d, 2)
  o.abstencao = row.a1 || 0
  d.abstencao = row.a2 || 0
  return {o, d}
}
somaMargens = (rows) =&gt; {
  const o = vazioO()
  const d = vazioD()
  for (const row of rows) {
    const m = margemDe(row)
    for (const k of ORIGENS) o[k] += m.o[k]
    for (const k of DESTINOS) d[k] += m.d[k]
  }
  return {o, d}
}
mapaDoModelo = (modelo, mun) =&gt; {
  const cidade = matriz.filter(d =&gt; d.uf === uf && String(d.modelo) === modelo && +d.municipio === +mun)
  const estado = matriz.filter(d =&gt; d.uf === uf && String(d.modelo) === modelo && +d.municipio === 0)
  const linhasTaxa = cidade.length ? cidade : estado
  const mapa = new Map()
  for (const d of linhasTaxa) mapa.set(`${String(d.origem)}|${String(d.destino)}`, num(d.taxa))
  return {mapa, propria: cidade.length &gt; 0, tem: linhasTaxa.length &gt; 0}
}
bpMapa = mapaDoModelo("brown_payne", municipio)
lpMapa = mapaDoModelo("lphom", municipio)
celulaAplicada = (taxas, o, ok, dk) =&gt; {
  const base = votosVis(o, ok)
  if (!base || !taxas.tem) return null
  let votos = 0
  let tem = false
  for (const oo of partes(ok)) {
    for (const dd of partes(dk)) {
      const taxa = taxas.mapa.get(`${oo}|${dd}`)
      if (taxa == null) continue
      tem = true
      votos += (o[oo] || 0) * taxa
    }
  }
  return tem ? Math.round(votos) : null
}
comAbst = linhasEscopo.filter(d =&gt; d.a1 != null && d.a2 != null)
margemConjunto = somaMargens(comAbst)
cidadeRows = votos.filter(d =&gt; d.municipio === +municipio && d.a1 != null && d.a2 != null)
margemCidade = somaMargens(cidadeRows)
divModelos = () =&gt; {
  let m = 0
  for (const o of ORIGENS) for (const d of DESTINOS) {
    const a = bpMapa.mapa.get(`${o}|${d}`)
    const b = lpMapa.mapa.get(`${o}|${d}`)
    if (a == null || b == null) continue
    m = Math.max(m, Math.abs(a - b) * 100)
  }
  return m
}
canto = () =&gt; {
  const origens = []
  for (const o of ORIGENS) {
    let mx = 0
    for (const d of DESTINOS) mx = Math.max(mx, bpMapa.mapa.get(`${o}|${d}`) || 0)
    if (mx &gt;= 0.999) origens.push(o)
  }
  return origens
}
ajustesCidade = VIS_D.map(dk =&gt; {
  const est = VIS_O.reduce((s, ok) =&gt; {
    const v = celulaAplicada(bpMapa, margemCidade.o, ok, dk)
    return s + (v || 0)
  }, 0)
  const obs = votosVis(margemCidade.d, dk)
  const rel = obs ? Math.abs(est - obs) / Math.abs(obs) : (est ? 1 : 0)
  return {dk, est, obs, rel}
})
motivos = [
  divModelos() &gt; 15 ? `divergência de ${divModelos().toLocaleString("pt-BR", {maximumFractionDigits: 1})} pp entre os modelos` : "",
  canto().length ? `solução de canto em ${canto().map(o =&gt; NOMES[o] || o).join(", ")}` : "",
  ajustesCidade.some(d =&gt; d.rel &gt; LIMIAR_RESIDUO) ? "Brown e Payne menos o divulgado da cidade passa de 5% em algum destino" : ""
].filter(Boolean)
instavel = motivos.length &gt; 0










































































































































































Plotly = require("https://cdn.plot.ly/plotly-2.35.2.min.js")
fluxoCidade = (taxas) =&gt; {
  if (!taxas.tem) return html``
  const nos = [
