esperado = (taxas, o, dk) =&gt; VIS_O.reduce((s, ok) =&gt; s + (celulaAplicada(taxas, o, ok, dk) || 0), 0)
obsTotal = VIS_D.reduce((s, dk) =&gt; s + votosVis(margemConjunto.d, dk), 0)
estTotal = (taxas) =&gt; VIS_D.reduce((s, dk) =&gt; s + esperado(taxas, margemConjunto.o, dk), 0)
ppFatia = (est, obs, totalEst, totalObs) =&gt; (totalEst && totalObs)
  ? 100 * (est / totalEst - obs / totalObs)
  : null
relativo = (est, obs) =&gt; obs ? Math.abs(est - obs) / Math.abs(obs) : (est ? 1 : 0)
notaFora = linhasEscopo.length - comAbst.length
tabelaModelo = (taxas, titulo) =&gt; {
  const o = margemCidade.o
  const grade = VIS_O.map(ok =&gt; VIS_D.map(dk =&gt; {
    const votos = celulaAplicada(taxas, o, ok, dk)
    const base = votosVis(o, ok)
    return votos == null ? null : {votos, taxa: base ? votos / base : null}
  }))
  const linha = grade.map(cols =&gt; cols.reduce((s, c) =&gt; s + (c ? c.votos : 0), 0))
  const taxaLinha = grade.map(cols =&gt; cols.reduce((s, c) =&gt; s + (c && c.taxa != null ? c.taxa : 0), 0))
  const coluna = VIS_D.map((_, j) =&gt; grade.reduce((s, cols) =&gt; s + (cols[j] ? cols[j].votos : 0), 0))
  return html`&lt;p&gt;&lt;strong&gt;${titulo}&lt;/strong&gt;&lt;/p&gt;
    &lt;div style="overflow-x:auto"&gt;&lt;table class="table table-sm"&gt;
      &lt;thead&gt;&lt;tr&gt;&lt;th&gt;1º turno&lt;/th&gt;${VIS_D.map(d =&gt; html`&lt;th&gt;${NOMES[d]}&lt;/th&gt;`)}&lt;th&gt;Total&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
