          &lt;th style="white-space:nowrap"&gt;${fmt(linha[i])} · ${pct1(taxaLinha[i])}&lt;/th&gt;
        &lt;/tr&gt;`)}
        &lt;tr&gt;&lt;th&gt;Total&lt;/th&gt;${coluna.map(v =&gt; html`&lt;th&gt;${fmt(v)}&lt;/th&gt;`)}&lt;th&gt;${fmt(linha.reduce((s, v) =&gt; s + v, 0))}&lt;/th&gt;&lt;/tr&gt;
      &lt;/tbody&gt;
    &lt;/table&gt;&lt;/div&gt;`
}
tabelaDif = () =&gt; html`&lt;p&gt;&lt;strong&gt;Diferença, lphom − Brown e Payne&lt;/strong&gt;&lt;/p&gt;
  &lt;div style="overflow-x:auto"&gt;&lt;table class="table table-sm"&gt;
